const sexKind = (sex) => (sex === "Male" ? "m" : sex === "Female" ? "f" : "n");
function nameList(country, kind) {
  const n = NAMES[country] || NAMES["United States"];
  const l = n[kind];
  return l && l.length ? l : n.m;
}

